// 문서 기준의 로컬 화면 시연. 실제 업무 시스템 연결 없음.
menus.unshift(['control','▣','작업·출하 관제']);menus.splice(6,0,['quality','✚','품질·실사']);menus.push(['shipping','⇢','포장·기사 인계'],['reservation','◷','예약 출고'],['devices','◉','장비·전송 상태'],['guide','≡','업무 정의·도움말']);
let taskStatus='전체',workerFilter='전체',workQuery='',detailTab='작업 정보';
function ops(){if(!state.ops)state.ops={owner:'김민수',request:false,accepted:false,repacked:false,scans:[],handoff:false,quality:false,count:false,device:false,offline:false};return state.ops}
const tasks=[{id:'000001',order:'000001',tote:'000077',client:'이지은',worker:'김민수',status:'피킹 중',goods:'물 2 · 우유 1',start:'14:01',elapsed:19,center:'PPC · 강남'},{id:'000003',order:'000002',tote:'000081',client:'허하나',worker:'박서연',status:'대기',goods:'물 1',start:'13:45',elapsed:35,center:'PPC · 강남'},{id:'000004',order:'000003',tote:'000082',client:'정민호',worker:'이수현',status:'피킹 중',goods:'물 1 · 계란 2',start:'14:10',elapsed:10,center:'PPC · 강남'},{id:'000005',order:'000004',tote:'000083',client:'박지훈',worker:'김태영',status:'완료',goods:'물 3',start:'13:52',elapsed:0,center:'PPC · 강남'},{id:'000006',order:'000005',tote:'000084',client:'김수진',worker:'홍지수',status:'패킹 중',goods:'물 1 · 우유 2',start:'14:12',elapsed:8,center:'PPC · 강남'},{id:'000007',order:'—',tote:'—',client:'센터 보충',worker:'최준호',status:'이관 집품',goods:'생수 12',start:'14:08',elapsed:12,center:'DC · 인천'}];
function taskRows(){return tasks.map(t=>({...t,worker:t.id==='000001'?ops().owner:t.worker})).filter(t=>($('#center').value==='전체 센터'||t.center===$('#center').value)&&(taskStatus==='전체'||t.status===taskStatus)&&(workerFilter==='전체'||t.worker===workerFilter)&&(t.order+t.tote+t.worker+t.goods).includes(workQuery))}
const tid=t=>'TSK-20261012-'+t.id, oid=t=>t.order==='—'?'센터 이관 작업':'ORD-20261012-'+t.order;
views.control=()=>head('OPERATIONS','작업·출하 관제','작업 진행, 담당자, 토트 위치와 예외를 함께 확인합니다.',`<button onclick="toast('14:20 기준 가상 현황을 다시 표시했습니다.');render()">↻ 현황 새로고침</button>`)+`<div class="control-layout"><div>${panel('운영자 작업 현황',`<div class="opsfilters"><label>상태<select onchange="taskStatus=this.value;render()">${['전체','대기','피킹 중','패킹 중','완료','이관 집품'].map(s=>`<option ${s===taskStatus?'selected':''}>${s}</option>`).join('')}</select></label><label>작업자<select onchange="workerFilter=this.value;render()">${['전체',...new Set(tasks.map(t=>t.id==='000001'?ops().owner:t.worker))].map(s=>`<option ${s===workerFilter?'selected':''}>${s}</option>`).join('')}</select></label><label>주문·토트·상품<input id="worksearch" placeholder="검색어 입력" value="${esc(workQuery)}" onchange="workQuery=this.value;render()"></label><button class="primary" onclick="render()">조회</button></div>`+table(['작업번호','주문·토트','고객·목적','작업자','상태','상품 내역','시작','경과',''],taskRows().map(t=>[`<button class="link" onclick="taskDetail('${t.id}')">${tid(t)}</button>`,`<small>${oid(t)}</small>TOTE-${t.tote}`,t.client,t.worker,pill(t.status,t.status==='대기'?'red':t.status==='완료'?'green':'blue'),t.goods,t.start,`${t.elapsed}분`,`<button onclick="taskDetail('${t.id}')">상세</button>`])),'14:20 기준 · 가상 작업')+panel('교대 이력 · 담당자 변경',table(['작업','이전 → 현재 담당','상태','기록'],[[tid(tasks[0]),`김민수 → ${ops().owner}`,pill(ops().accepted?'인계 완료':ops().request?'인계 대기':'변경 없음',ops().accepted?'green':'amber'),ops().accepted?'완료분·잔여분·실물 토트 확인':'작업번호 유지 · 인계 수락 전 담당 유지']]))}</div><div>${panel('작업 상태 요약',`<div class="summarytiles">${[['전체',tasks.length],['피킹 중',2],['대기',1],['패킹 중',1],['완료',1],['이관 집품',1]].map(([a,b])=>`<button onclick="taskStatus='${a}';render()"><b>${b}</b><span>${a}</span></button>`).join('')}</div>`)}${panel('오래 대기한 작업 TOP 5',table(['작업','작업자','경과'],tasks.filter(t=>t.status!=='완료').sort((a,b)=>b.elapsed-a.elapsed).slice(0,5).map(t=>[`<button class="link" onclick="taskDetail('${t.id}')">…${t.id}</button>`,t.worker,`<span class="delay">${t.elapsed}분</span>`]))) }<div class="notice amber">경과시간은 시연값입니다. 지연 판정 기준·작업 잠금 만료시간은 미결정 정책입니다.</div></div></div>`;
function taskDetail(id){const t=tasks.find(t=>t.id===id),main=id==='000001';modal(`<h2>작업 상세 · ${tid(t)}</h2><p class="mini">${oid(t)} · 작업번호는 교대 후에도 유지합니다.</p><div class="detailgrid"><div><small>토트 / 실물 위치</small><b>TOTE-${t.tote} / A-3-2</b></div><div><small>담당 / 상태</small><b>${main?ops().owner:t.worker} / ${t.status}</b></div><div><small>완료분</small><b>${main?'생수 2 / 2개':t.goods}</b></div><div><small>잔여분</small><b>${main?'우유 1 / 1개 미완료':'작업별 상세 확인'}</b></div></div>${table(['시간','상품·처리','수량','결과'],[['14:00:32','토트 연결','—',pill('확인 완료','green')],['14:00:58','생수 2L 스캔','1 / 2',pill('반영','green')],['14:01:22','생수 2L 스캔','2 / 2',pill('반영','green')],['14:02:10','다른 상품 스캔','—',pill('오상품 차단','red')]])}<div class="notice">인계 전 실물 토트·완료분·잔여분을 확인합니다. 이전 담당자의 늦은 요청은 현재 담당·버전을 재검증해야 합니다.</div>${main?`<div class="actions"><button onclick="requestHandover()" ${ops().accepted?'disabled':''}>담당자 변경 요청</button>${ops().request&&!ops().accepted?`<button class="primary" onclick="acceptHandover()">후임 확인·인계 수락</button>`:''}</div>`:''}`)}
function requestHandover(){doAction(()=>ops().request=true,'김민수 → 박서연 인계 요청 · 수락 전에는 현재 담당 유지')}
function acceptHandover(){modal(`<h2>교대 인계 확인</h2><p>생수 2개 완료 · 우유 1개 잔여 · 토트 TOTE-000077 · A-3-2</p><label><input id="totecheck" type="checkbox"> 후임이 실물 토트와 완료분·잔여분을 확인했습니다.</label><div class="actions"><button onclick="closeModal()">닫기</button><button class="primary" onclick="if(!$('#totecheck').checked){toast('실물·잔여분 확인이 필요합니다.');return}doAction(()=>{ops().owner='박서연';ops().accepted=true},'인계 수락 · 같은 TSK 작업번호로 박서연에게 담당 변경')">인계 수락</button></div>`)}
views.quality=()=>head('QUALITY & COUNT','품질·격리·재고 실사','판매 적합 판정, 실제 처분, 재고 차이 조정을 구분합니다.')+panel('품질 격리·처분',table(['문서','상품·로트','수량','현재 상태',''],[['QLT-20261012-000001<small>품질 격리</small>','우유 1L · 내부 로트 L01','12개',pill('격리 · 피킹 제외','red'),`<button onclick="qualityDetail()">검토</button>`]]))+panel('재고 실사·조정 요청',table(['실사 문서','위치·상품','장부 / 계수 / 재계수','조정',''],[['CNT-20261012-000001<small>재고 실사</small>','PPC 강남 · 생수','10 / 8 / 8개',pill(ops().count?'조정 검토 요청':'차이 −2','amber'),`<button onclick="countDetail()">근거 확인</button>`]]))+`<div class="notice amber">실사 중 작업 중단 여부·격리 해제 기준·폐기 결재선·조정 승인 기준은 정책 미정입니다. 근거 없이 수량을 맞추거나 자동 승인하지 않습니다.</div>`;
function qualityDetail(){modal(`<h2>격리 상품 · 처분 검토</h2><p>QLT(품질 격리) · 우유 12개 · 판매·피킹 제외</p><div class="steps"><span>격리 등록</span><span>재검수</span><span>해제 / 반품 / 폐기 판단</span><span>승인·실행</span></div><div class="notice">소비기한이 빠르다는 이유로 격리 상품을 피킹하지 않습니다. 폐기 요청 DSP와 실제 실행은 별도이며 중복 요청은 재고에 한 번만 반영합니다.</div><div class="actions"><button class="primary" onclick="doAction(()=>ops().quality=true,'격리 상품 재검수 요청 기록 · 실물 수량은 유지')">재검수 요청</button></div>`)}
function countDetail(){modal(`<h2>실사 차이 · 재고 조정 검토</h2>${table(['확인 항목','결과'],[['장부 / 1차 / 재계수','10 / 8 / 8개'],['기준시각 이후 이동','확인 필요'],['ADJ(재고 조정) 요청','차이 −2 · 승인 미확정']])}<div class="notice amber">재계수와 이동내역을 검증한 뒤 권한자가 조정합니다. 이 버튼은 검토 요청만 기록합니다.</div><div class="actions"><button class="primary" onclick="doAction(()=>ops().count=true,'ADJ(재고 조정) 검토 요청 기록 · 원장 미반영')">조정 검토 요청</button></div>`)}
function packages(){return [1,ops().repacked?4:2,3]}
views.shipping=()=>head('OUTBOUND','포장·출고·기사 인계','유효 포장과 실제 전달 결과를 확인하고 전체 인계를 마칩니다.')+metrics([['출하 문서','SHP','고객 주문 시 생성 · 출하 단위'],['유효 포장','3개','상온 · 냉장 · 냉동 구분'],['전달 확인',`${ops().scans.length} / 3`,'전체 전달 시 인계 완료'],['인계 상태',ops().handoff?'완료':'확인 중','재고원장 반영 시점과 별개']])+panel('출하 대상·포장',table(['출하','포장번호','구성','상태',''],packages().map((n,i)=>['SHP-20261012-000001',`PKG-20261012-${String(n).padStart(6,'0')}`,['물 2개 · 상온','우유 2개 · 냉장','만두 2개 · 냉동'][i],pill(ops().scans.includes(n)?'전달 확인':'준비 완료',ops().scans.includes(n)?'green':'blue'),`<button onclick="deliverPackage(${n})" ${ops().scans.includes(n)?'disabled':''}>전달 확인 시연</button>`])))+`<div class="actions"><button onclick="repack()" ${ops().handoff?'disabled':''}>냉장 포장 교체</button><button onclick="toast('같은 PKG 번호로 라벨 재출력 이력을 기록했습니다.')">라벨 재출력</button><button class="primary" onclick="finishHandoff()" ${ops().handoff?'disabled':''}>기사·전체 포장 확인</button></div><div class="notice" style="margin-top:20px">포장 교체는 새 PKG(실물 포장 식별자), 라벨 재출력은 같은 PKG입니다. 일부 전달은 별도로 추적하며 전체 완료로 표시하지 않습니다.</div>`;
function deliverPackage(n){modal(`<h2>실제 전달 확인 시연</h2><p>지정 기사 R01 · 해당 출하의 유효 PKG-20261012-${String(n).padStart(6,'0')}</p><div class="notice">잘못된 주문·무효 포장·다른 기사일 때는 처리할 수 없습니다. 이 시연은 일치하는 대상의 전달 기록입니다.</div><div class="actions"><button class="primary" onclick="doAction(()=>{if(!ops().scans.includes(${n}))ops().scans.push(${n})},'포장 ${n} 전달 확인 · 전체 인계 여부 별도 판단')">실물 전달 확인</button></div>`)}
function repack(){if(ops().repacked){toast('교체된 유효 포장은 001·004·003입니다.');return}if(ops().scans.includes(2)){toast('이미 전달한 포장은 회수·실물 상태 확인 후 교체해야 합니다.');return}doAction(()=>ops().repacked=true,'PKG 002 무효 → 004 교체 · 총 유효 포장 3개 유지')}
function finishHandoff(){if(ops().scans.length!==3){toast('유효 포장 전체가 전달되어야 인계를 완료할 수 있습니다.');return}modal(`<h2>기사 인계 완료 확인</h2><p>지정 기사 R01 · 유효 포장 3개 모두 전달 확인</p><div class="notice amber">HOV(기사 인계) 완료를 기록합니다. 재고원장 차감 시점은 미결정이므로 이 시안에서 자동 차감하지 않습니다.</div><div class="actions"><button class="primary" onclick="doAction(()=>ops().handoff=true,'HOV(기사 인계) 완료 · 유효 포장 전체 전달 확인')">인계 완료 기록</button></div>`)}
views.reservation=()=>head('RESERVATION','예약 출고·작업 분산','예약 수령시간, 예정재고, 작업 준비와 배달 요청을 함께 봅니다.')+panel('예약 주문 관제',table(['주문','수령 약속','현물 / 예정','작업 요청','배달 요청',''],[['ORD-20261012-000020','19:00 ~ 21:00','현물 확보','여유·품질 구간 검토',pill('시간 맞춰 요청','blue'),`<button onclick="reservationDetail(false)">일정 상세</button>`],['ORD-20261012-000021','19:00 ~ 21:00','예정 입고 2개','입고 확인 대기',pill('약속 유지·상태 확인','amber'),`<button onclick="reservationDetail(true)">재고 대기</button>`]]))+panel('출고 준비와 배달 요청',`<div class="flow">${[['수령 약속','고객 시간 확인'],['예정재고 확인','현물과 별도 관리'],['작업 분산','현장 여유·품질 구간'],['포장·보관','상품별 조건 유지'],['배달 요청','수령시간 맞춰 요청'],['기사 인계','실물 전체 전달']].map(([a,b])=>`<button onclick="reservationDetail(false)"><b>${a}</b><small>${b}</small></button>`).join('')}</div>`)+`<div class="notice amber">이미지의 고정 ‘출발 30분 전’·슬롯 건수·온도는 기본 정책으로 적용하지 않았습니다. 최대 대기시간·고객 슬롯 판매 상한은 별도 결정 항목입니다.</div>`;
function reservationDetail(short){modal(`<h2>${short?'예정재고 대기':'예약 출고 일정 검토'}</h2><p>수령 약속 19:00 ~ 21:00 · 가상 주문</p><div class="notice">${short?'확정 예정 물량을 현재 현물에 더하지 않습니다. 재고 부족 작업은 보류하고 입고·최종 출고 가능시각을 다시 확인합니다. 고객 연락·취소 규칙은 미결정입니다.':'현장 작업 여유와 상품 품질 유지 범위에서 준비를 분산합니다. 출고 준비 요청과 배달 요청을 분리해 수령시간에 맞춥니다.'}</div><div class="actions"><button onclick="closeModal()">확인</button></div>`)}
views.devices=()=>head('SYSTEM STATUS','장비·전송 상태','단말·라벨 장비와 오프라인 임시 기록을 확인합니다.')+panel('장비 상태 모니터링',table(['장비','상태','최근 동기화',''],[['PDA(현장 작업 단말)',pill('정상','green'),'14:19','조회·스캔'],['라벨 프린터',pill('정상','green'),'14:18','출력 가능'],['무선 AP',pill(ops().device?'정상':'오프라인',ops().device?'green':'red'),ops().device?'14:20':'14:05',`<button onclick="doAction(()=>ops().device=true,'무선 AP 연결 재확인 시연 · 정상 상태 표시')">재확인</button>`],['관제 서버',pill('정상','green'),'14:20','시연 표시']]))+panel('오프라인 기록·재전송',table(['요청','작업','임시 상태',''],[['요청 UUID 동일 유지','TSK-20261012-000001',pill(ops().offline?'유효성 확인 후 반영':'임시저장 1건',ops().offline?'green':'amber'),`<button onclick="syncOffline()">재연결 시연</button>`]]))+`<div class="notice">오프라인 임시 기록은 최종 확정과 다릅니다. 재연결 후 주문 취소·담당 변경·이미 처리된 요청을 확인하고 유효한 요청만 반영합니다.</div>`;
function syncOffline(){if(ops().offline){toast('동일 요청은 기존 결과를 반환합니다. 추가 반영하지 않습니다.');return}doAction(()=>ops().offline=true,'같은 요청 UUID 재전송 · 유효성 검증 후 1회 반영 시연')}
views.guide=()=>head('REFERENCE','업무 정의·도움말','최신 아웃풋 문서를 기준으로 화면을 구성했습니다.')+`<div class="notice">사전조사 이미지는 화면 구성 참고입니다. 충돌 시 아웃풋 문서의 채번·실사례 우선 정책을 적용합니다.</div>`+panel('문서별 업무 정의',table(['업무 문서','읽기'],Object.keys(window.projectDocs||{}).map(n=>[esc(n.replace('.md','')),`<button onclick="readDefinition('${n}')">정의 보기</button>`])))+panel('자주 쓰는 약어',table(['코드','짧은 뜻'],[['ADJ','재고 조정'],['CNT','재고 실사'],['SHP','출하'],['TSK','작업 식별자'],['PKG','실물 포장 식별자'],['HOV','기사 인계'],['RCV','공급사 입고·검수'],['TIN','센터 이송 도착']]));
function readDefinition(n){modal(`<h2>${esc(n.replace('.md',''))}</h2><pre class="docread">${esc(window.projectDocs[n])}</pre>`)}
// 초기 화면은 이미지의 작업·출하 관제로 구성.
page='control';render();

